
(()=>{'use strict';const M=window.Matchsik,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];const tokenKey='matchsik_admin_token';let token=sessionStorage.getItem(tokenKey)||'',tab='summary',apps=[];async function api(path,opt={}){return M.api(path,{...opt,token})}function auth(){if(token){$('#adminAuth').hidden=true;$('#adminApp').hidden=false;load()}else{$('#adminAuth').hidden=false;$('#adminApp').hidden=true}}$('#adminLogin').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));try{const r=await M.api('/admin/login',{method:'POST',body:JSON.stringify(f)});token=r.token;sessionStorage.setItem(tokenKey,token);auth()}catch(err){$('#adminLoginError').innerHTML=`<div class="error">${M.esc(err.message)}</div>`}};$('#adminLogout').onclick=()=>{token='';sessionStorage.removeItem(tokenKey);auth()};function summaryHtml(data){return `<section class="portal-hero"><span class="eyebrow">OPERATIONS</span><h1>운영 현황</h1></section><div class="trust-grid"><div class="trust-card"><b>${data.total||0}건</b><span>전체 신청</span></div><div class="trust-card"><b>${data.paymentReview||0}건</b><span>입금 확인 필요</span></div><div class="trust-card"><b>${data.approved||0}건</b><span>확정 수업</span></div><div class="trust-card"><b>${data.nextLessons||0}건</b><span>예정 수업</span></div></div>`}function actions(a){const b=[];if(a.status==='PAYMENT_REPORTED'||a.status==='PAYMENT_REVIEW')b.push(`<button class="btn btn-secondary" data-action="confirm-payment" data-code="${a.code}">입금 확인</button>`);if(a.status==='PAYMENT_CONFIRMED')b.push(`<button class="btn btn-primary" data-action="approve" data-code="${a.code}">수강 승인</button>`);if(!['CANCELLED','EXPIRED','REFUNDED'].includes(a.status))b.push(`<button class="btn btn-secondary" data-action="cancel" data-code="${a.code}">취소</button>`);return b.join(' ')}function appHtml(){return `<section class="portal-hero"><span class="eyebrow">APPLICATIONS</span><h1>수강 신청 관리</h1></section><section class="portal-panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>신청일</th><th>수강생</th><th>자격증</th><th>강사</th><th>금액</th><th>상태</th><th>처리</th></tr></thead><tbody>${apps.map(a=>`<tr><td>${String(a.created_at||'').slice(0,10)}</td><td>${M.esc(a.student_name)}<br><small>${M.esc(a.phone)}</small></td><td>${M.esc(a.cert)} ${M.esc(a.course)}</td><td>${M.esc(a.teacher_name)}</td><td>${M.money(a.amount)}</td><td>${M.esc(a.status)}</td><td>${actions(a)}</td></tr>`).join('')||'<tr><td colspan="7">신청이 없습니다.</td></tr>'}</tbody></table></div></section>`}async function load(){try{const [sum,ap]=await Promise.all([api('/admin/summary'),api('/admin/applications')]);apps=ap.items||[];if(tab==='summary')$('#adminView').innerHTML=summaryHtml(sum);else if(tab==='applications')$('#adminView').innerHTML=appHtml();else{$('#adminView').innerHTML='<section class="portal-hero"><span class="eyebrow">TEACHERS</span><h1>강사 관리</h1></section><section class="portal-panel"><div id="matchsikAdminTeachersV28"></div></section>';window.MATCHSIK_V28_ADMIN_TEACHERS?.open?.()}bind()}catch(err){if(err.status===401||err.status===403){token='';sessionStorage.removeItem(tokenKey);auth()}else $('#adminView').innerHTML=`<div class="error">${M.esc(err.message)}</div>`}}function bind(){$$('[data-admin-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.adminTab;$$('[data-admin-tab]').forEach(x=>x.classList.toggle('active',x===b));load()});$$('[data-action]').forEach(b=>b.onclick=async()=>{let reason='';if(b.dataset.action==='cancel')reason=prompt('취소 사유를 입력하세요.')||'';if(!confirm('처리하시겠습니까?'))return;try{await api(`/admin/applications/${encodeURIComponent(b.dataset.code)}/action`,{method:'POST',body:JSON.stringify({action:b.dataset.action,reason})});M.toast('처리했습니다.');load()}catch(err){alert(err.message)}})}auth()})();
